import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"LSASS protection","description":"","frontmatter":{"grammarly":false,"search":{"exclude":true}},"headers":[],"relativePath":"d/ad/lsass-protection.md","filePath":"d/ad/lsass-protection.md","lastUpdated":1781102819000}`),a={name:`d/ad/lsass-protection.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/ad/lsass-protection.md for this page in Markdown format</div><h1 id="lsass-protection" tabindex="-1">LSASS protection <a class="header-anchor" href="#lsass-protection" aria-label="Permalink to “LSASS protection”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>The Local Security Authority Subsystem Service is a process in Microsoft Windows operating systems that is responsible for enforcing security policy on the system. For this purpose, among other things, it temporarily stores the credentials of logged-in users in order to perform authentications against other systems (e.g. when opening a file share).</p><p>Depending on the operating system version, either plain-text passwords or only NT hashes are stored by default. However, NT hashes are similarly critical as passwords, since they can be used for authentication via pass-the-hash.</p><p>To protect this critical process, the vendor provides several methods, including &quot;Credential Guard&quot; and &quot;LSA Protection&quot; (RunAsPPL).</p><p>Credential Guard is a virtualization-based isolation technology for LSASS in which credentials are stored in a memory area protected by the processor. Access to credentials protected in this way is not possible. However, you should note that this only protects credentials that are already cached. An attacker could still intercept the credentials of new authentication processes.</p><p>LSA Protection (RunAsPPL) is a protection mechanism in the Windows kernel that protects the memory of the LSASS process from access. However, since this is a kernel feature, it can be bypassed by kernel modules. It should still be enabled along with Credential Guard. Loading a malicious kernel module provides versatile opportunities for AV/EDR/HIDS systems to detect the attack, making the attack more difficult.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p>Credential Guard and LSA Protection should be enabled on all systems.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};